('function continueAfterVote(state: GroupGameState, accusedId: string, now: number): VoteResolution {\n  const roundExpired = state.roundEndsAt !== null && now >= state.roundEndsAt;\n  if (roundExpired) {\n    return { state: finishGroupRound(state, "spies", "Час сплив, і голосування не завершилося стратою шпигуна."), resolved: true, accusedId, result: "spies_win" };\n  }\n  return {\n    state: {\n      ...state,\n      status: "playing",\n      phase: "choose_target",\n      voteStage: null,\n      accusedId: null,\n      executionVotes: {},\n      voteEndsAt: null,\n      activeAskerId: state.players[Math.floor(Math.random() * state.players.length)]?.id || null,\n      targetId: null,\n      pendingQuestionIndex: null,\n    },\n    resolved: true,\n    accusedId,\n    result: "continue",\n  };\n}', 'function continueAfterVote(state: GroupGameState, accusedId: string, now: number, eliminatedId?: string): VoteResolution {\n  const eliminatedPlayerIds = eliminatedId\n    ? [...new Set([...(state.eliminatedPlayerIds || []), eliminatedId])]\n    : [...(state.eliminatedPlayerIds || [])];\n  const nextState: GroupGameState = {\n    ...state,\n    status: "playing",\n    phase: "choose_target",\n    eliminatedPlayerIds,\n    votes: {},\n    voteStage: null,\n    accusedId: null,\n    executionVotes: {},\n    voteEndsAt: null,\n    activeAskerId: null,\n    targetId: null,\n    pendingQuestionIndex: null,\n  };\n  const active = activeGroupPlayers(nextState);\n  const spies = active.filter(player => player.role === "spy").length;\n  const agents = active.length - spies;\n  if (spies === 0) {\n    return { state: finishGroupRound(nextState, "civilians", "Усіх шпигунів викрито. Агенти перемогли."), resolved: true, accusedId, result: "civilians_win" };\n  }\n  if (agents === 0 || (spies === 1 && agents === 1)) {\n    return { state: finishGroupRound(nextState, "spies", "Залишилися один шпигун і один агент. Шпигун переміг."), resolved: true, accusedId, result: "spies_win" };\n  }\n  if (state.roundEndsAt !== null && now >= state.roundEndsAt) {\n    return { state: finishGroupRound(nextState, "spies", "Час раунду сплив. Перемогли шпигуни."), resolved: true, accusedId, result: "spies_win" };\n  }\n  const nextAsker = active[randomInt(active.length)];\n  return { state: { ...nextState, activeAskerId: nextAsker?.id || null }, resolved: true, accusedId, result: "continue" };\n}',1),
('function resolveExecutionVote(state: GroupGameState, now: number): VoteResolution {\n  const accusedId = state.accusedId || undefined;\n  if (!accusedId) return { state, resolved: false };\n  const votes = state.executionVotes || {};\n  const yesCount = Object.values(votes).filter(Boolean).length;\n  const required = Math.floor(state.players.length / 2) + 1;\n  const timedOut = state.voteEndsAt !== null && now >= state.voteEndsAt;\n  if (!timedOut) return { state, resolved: false, accusedId };\n  if (yesCount >= required) {\n    const accused = state.players.find(player => player.id === accusedId);\n    if (accused?.role === "spy") {\n      return {\n        state: { ...state, status: "spy_guess", phase: "spy_guess", guesserId: accused.id, guessEndsAt: now + 60_000, voteEndsAt: null },\n        resolved: true,\n        accusedId,\n        result: "spy_guess",\n      };\n    }\n    return {\n      state: finishGroupRound(state, "spies", "Агенти стратили невинного підозрюваного."),\n      resolved: true,\n      accusedId,\n      result: "spies_win",\n    };\n  }\n  return continueAfterVote(state, accusedId, now);\n}', 'function resolveExecutionVote(state: GroupGameState, now: number): VoteResolution {\n  const accusedId = state.accusedId || undefined;\n  if (!accusedId) return { state, resolved: false };\n  const votes = Object.entries(state.executionVotes || {}).filter(([voterId]) => isActiveGroupPlayer(state, voterId));\n  const yesCount = votes.filter(([, approve]) => approve).length;\n  const activeCount = activeGroupPlayers(state).length;\n  const required = Math.floor(activeCount / 2) + 1;\n  const timedOut = state.voteEndsAt !== null && now >= state.voteEndsAt;\n  if (!timedOut) return { state, resolved: false, accusedId };\n  if (yesCount >= required) {\n    const accused = state.players.find(player => player.id === accusedId);\n    if (!accused || !isActiveGroupPlayer(state, accusedId)) return continueAfterVote(state, accusedId, now);\n    if (accused.role === "spy") {\n      const eliminatedPlayerIds = [...new Set([...(state.eliminatedPlayerIds || []), accused.id])];\n      return {\n        state: finishGroupRound({ ...state, eliminatedPlayerIds }, "civilians", `Шпигуна ${accused.username ? `@${accused.username}` : accused.firstName} страчено. Гра завершена негайно.`),\n        resolved: true,\n        accusedId,\n        result: "civilians_win",\n      };\n    }\n    return continueAfterVote(state, accusedId, now, accusedId);\n  }\n  return continueAfterVote(state, accusedId, now);\n}',1),
