('export function guessGroupSecret(state: GroupGameState, userId: string, guess: string, now = Date.now()): GroupGameState {\n  if (state.status !== "spy_guess" || state.phase !== "spy_guess") throw new Error("Зараз не можна вгадувати секрет.");\n  if (state.guessEndsAt !== undefined && state.guessEndsAt !== null && now >= state.guessEndsAt) throw new Error("Час на останній здогад сплив.");\n  const player = state.players.find(candidate => candidate.id === userId);\n  if (!player || player.role !== "spy" || (state.guesserId && state.guesserId !== userId)) throw new Error("Вгадувати може лише викритий шпигун.");\n  const correct = normalizeGuess(guess) === normalizeGuess(state.secret || "");\n  const modeLabel = state.mode === "secret_word" ? "слово" : "локацію";\n  return finishGroupRound(state, correct ? "spies" : "civilians", correct ? `Шпигун правильно вгадав ${modeLabel}.` : `Шпигун не вгадав ${modeLabel}.`);\n}\n\n','',1),
('export function tickGroupRound(state: GroupGameState, now = Date.now()): VoteResolution {\n  if (state.status === "spy_guess" && state.guessEndsAt !== undefined && state.guessEndsAt !== null && now >= state.guessEndsAt) {\n    return { state: finishGroupRound(state, "civilians", "Шпигун не встиг вгадати секрет."), resolved: true, result: "civilians_win" };\n  }','export function tickGroupRound(state: GroupGameState, now = Date.now()): VoteResolution {\n  if (state.status === "spy_guess") {\n    const spy = state.players.find(player => player.id === state.guesserId);\n    const name = spy ? (spy.username ? `@${spy.username}` : spy.firstName) : "Шпигун";\n    return { state: finishGroupRound(state, "civilians", `Шпигуна ${name} страчено. Гра завершена негайно.`), resolved: true, result: "civilians_win" };\n  }',1),
('\nfunction normalizeGuess(value: string) {\n  return value.toLocaleLowerCase("uk-UA").normalize("NFKC").replace(/[’\'`]/g, "\'").replace(/[\\s.,!?—–-]+/g, " ").trim();\n}\n','\n',1),
